import { createTheme, defaultVariantColorsResolver, parseThemeColor, type CSSVariablesResolver, type MantineColorsTuple, type VariantColorsResolver } from "@mantine/core";

export const palette = {
  background: "#EDF0F2",
  surface: "#FFFFFF",
  ink: "#172030",
  steel: "#56657A",
  brass: "#B8862B",
  breach: "#B23A2E",
  cleared: "#2F7A57",
  line: "#D5DAE0",
} as const;

// Index 6 is the brand value. Generated by mixing toward white (0-5) and black (7-9).
const brass: MantineColorsTuple = ["#F9F5EE", "#F2E9D9", "#E7D6B7", "#DCC395", "#D0AF73", "#C49B4F", "#B8862B", "#976E23", "#79581C", "#604616"];
const breach: MantineColorsTuple = ["#F9EFEE", "#F1DCD9", "#E5BCB8", "#D99D97", "#CC7D75", "#BF5B52", "#B23A2E", "#923026", "#75261E", "#5D1E18"];
const cleared: MantineColorsTuple = ["#EEF4F2", "#DAE7E1", "#B8D2C6", "#97BDAB", "#76A790", "#529174", "#2F7A57", "#276447", "#1F5139", "#183F2D"];
const steel: MantineColorsTuple = ["#F1F3F4", "#E1E3E7", "#C6CBD2", "#ABB2BD", "#8F99A7", "#737F91", "#56657A", "#475364", "#394351", "#2D353F"];
const ink: MantineColorsTuple = ["#ECEDEE", "#D5D7DA", "#B0B3B9", "#8B9098", "#666C76", "#3E4653", "#172030", "#131A27", "#0F1520", "#0C1119"];

const CUSTOM = new Set(["brass", "breach", "cleared", "steel", "ink"]);

/**
 * Light variants use shade 8 for text so badges stay above 4.5:1 on their tint.
 * Filled brass uses shade 7 (white text is 4.6:1 there, only 3.2:1 on the base).
 */
const variantColorResolver: VariantColorsResolver = (input) => {
  const base = defaultVariantColorsResolver(input);
  const parsed = parseThemeColor({ color: input.color ?? input.theme.primaryColor, theme: input.theme });
  if (!parsed.isThemeColor || !CUSTOM.has(parsed.color)) return base;
  const shades = input.theme.colors[parsed.color];
  if (input.variant === "light") {
    return { ...base, background: shades[0], hover: shades[1], color: shades[8], border: `1px solid ${shades[1]}` };
  }
  if (input.variant === "filled" && parsed.color === "brass") {
    return { ...base, background: shades[7], hover: shades[8], color: "#fff" };
  }
  return base;
};

export const theme = createTheme({
  primaryColor: "brass",
  primaryShade: 7,
  colors: { brass, breach, cleared, steel, ink },
  black: palette.ink,
  fontFamily: '"Public Sans", system-ui, -apple-system, "Segoe UI", sans-serif',
  fontFamilyMonospace: 'ui-monospace, "SF Mono", Consolas, monospace',
  headings: {
    fontFamily: '"Bricolage Grotesque", "Public Sans", system-ui, sans-serif',
    fontWeight: "650",
  },
  defaultRadius: "sm",
  focusRing: "auto",
  cursorType: "pointer",
  variantColorResolver,
  components: {
    Badge: { defaultProps: { radius: "sm", tt: "none" } },
    Button: { defaultProps: { fw: 600 } },
    Paper: { defaultProps: { radius: "md" } },
    Drawer: { defaultProps: { overlayProps: { backgroundOpacity: 0.3, blur: 1 } } },
  },
});

export const cssVariablesResolver: CSSVariablesResolver = () => ({
  variables: {
    "--sw-surface": palette.surface,
    "--sw-line": palette.line,
    "--sw-steel": palette.steel,
    "--sw-brass": palette.brass,
  },
  light: {
    "--mantine-color-body": palette.background,
    "--mantine-color-text": palette.ink,
    "--mantine-color-dimmed": palette.steel,
    "--mantine-color-default-border": palette.line,
  },
  dark: {},
});
